beh('B_election','A2','raft.Step, hup, campaign, stepCandidate','Local node term and active voter configuration','Tick or Campaign, eligible vote requests and responses',['S_campaign','S_dispatch','S_roles','S_joint','S_send'],implementation_guards=['Campaign requires local voter eligibility, no pending snapshot, and no unapplied committed configuration change.','Vote eligibility uses recorded vote/current leader and candidate last log term/index; joint vote result requires both majorities.','Response type must match candidate versus pre-candidate phase.'],writes=['Real election increments term and records self vote; pre-election does neither.','Winning real votes installs leader and appends a current-term empty entry.'],external_effects=['Vote and append responses, including self-votes, await the storage completion path.'],produces_fact_ids=['F_authority'],consumes_fact_ids=['F_config'],cross_activity_effects={'A1':'Leader authority selects the term used to qualify replication support and new commitment.'})
beh('B_context_reset','A2','raft.Step, reset, becomeFollower','Node term, leader role and volatile aggregation','Higher-term message, accepted leader message while candidate, or failed quorum check',['S_dispatch','S_commit_reset','S_roles','S_proposal'],writes=['New term clears vote; resets election timers, vote tally, per-peer progress, pendingConfIndex, transfer target and readOnly heartbeat-ack queue.','Preserves raftLog and committed entries across role changes.'],important_branches=['Future pre-votes and successful pre-vote responses do not change local term; a recent leader lease may reject disruptive vote requests.','Lower-term protocol messages are ignored or answered with current term; old storage append completions cannot stabilize entries, but snapshot completion remains applicable.','pendingReadIndexMessages is not cleared by reset, unlike readOnly.'],produces_fact_ids=['F_authority'],cross_activity_effects={'A1':'Old replication support is not retained as current leader match evidence; established committed history survives.'},unknowns=['Determine whether retained pre-commit read requests can affect semantics after authority changes; no violation inferred from retention.'])
beh('B_replication','A1','stepLeader, handleAppendEntries, handleHeartbeat','Leader term, per-peer Match and local log prefix','Proposal, MsgApp, MsgAppResp, heartbeat and retry',['S_proposal','S_send','S_commit_reset','S_ack','S_receive','S_log_append','S_log_context','S_tracker_commit','S_joint'],implementation_guards=['Leader drops proposals during transfer or when its progress is absent; limits uncommitted bytes.','Follower requires matching previous entry term and forbids overwriting committed entries.','Leader uses configured quorum match index and only commits an index whose log term equals current term.'],writes=['Assigns proposal index/term; appends unstable entries; durable acknowledgements update Match; successful maybeCommit advances committed.'],external_effects=['Successful ack-driven commitment releases pending reads and broadcasts appends.','Heartbeat commit is capped at recipient Match; rejection/backoff and heartbeat responses resume replication.'],produces_fact_ids=['F_committed'],consumes_fact_ids=['F_authority','F_config'],async_boundaries=['Replication acknowledgements are queued until caller storage completion.'])
beh('B_storage_ready','A6','RawNode Ready/acceptReady/Advance and caller storage workers','Per-node Ready batches and term-tagged append completion','Ready acceptance and conventional Advance or asynchronous append/apply responses',['S_usage','S_async_contract','S_ready_contract','S_raw_ready','S_raw_storage','S_raw_completion','S_dispatch'],legal_preconditions=['Caller persists required state and preserves Ready processing order; async messages to each local worker are reliable and ordered.'],writes=['Tracks in-progress unstable writes and application batches; append completion removes matching stable entries; apply completion advances applied.'],external_effects=['Non-async Advance dispatches captured local responses; async Ready emits worker messages with dependent response lists.'],important_branches=['Async application only exposes locally stable committed entries; conventional application may use unstable entries under the Ready persistence contract.'],consumes_fact_ids=['F_committed'],cross_activity_effects={'A1':'Persist-before-response makes acknowledgement support usable across crashes.','A2':'Term-tagged append completions distinguish old writes from current unstable state.','A5':'Ordered application completions update applied state and can trigger automatic configuration exit.'})
beh('B_application','A5','raft.appliedTo and raftLog application accounting','Committed/applied/applying indexes and configuration currently active at node','MsgStorageApplyResp, conventional Advance, or snapshot completion',['S_auto_leave','S_log_apply','S_log_commit','S_raw_completion','S_dispatch'],writes=['Advances applied monotonically and releases application byte pressure.'],important_branches=['When AutoLeave is true, applied reaches pendingConfIndex and this node is leader, proposes empty ConfChangeV2.','The proposal can be rejected while a leadership transfer is active; code relies on a later applied entry to retry.'],consumes_fact_ids=['F_committed','F_config'],cross_activity_effects={'A2':'Automatic joint exit proposal determines when authority can transition from joint voters to incoming voters.'},unknowns=['Does caller-owned ordinary Ready processing guarantee another appliedTo callback after a transfer rejects the only automatic exit attempt?'])
beh('B_configuration','A4','raft.applyConfChange, switchToConfig and confchange.Changer','Applied ConfChangeV2 and active incoming/outgoing voter sets','Caller applies committed membership entry, or configuration is restored from snapshot',['S_node_contract','S_conf_contract','S_config','S_confchange','S_tracker','S_restore_config'],implementation_guards=['Simple changes alter at most one voter; EnterJoint refuses already-joint state; LeaveJoint requires outgoing voters.','Proposal admission serializes configuration changes behind applied pendingConfIndex and requires leaving joint state before another change.'],writes=['Installs incoming/outgoing voters, learners and staged learners; sets AutoLeave on EnterJoint and clears it on LeaveJoint.'],important_branches=['Leader removal/demotion may step down depending on StepDownOnRemoval; otherwise proposals are constrained separately.','switchToConfig reevaluates commitment and broadcasts if it changes, but does not call releasePendingReadIndexMessages.'],produces_fact_ids=['F_config','F_committed'],cross_activity_effects={'A1':'Installed joint voter sets determine eligible acknowledgement and vote quorums.','A2':'Applied configuration changes determine eligibility for future campaigns and transferred leadership.'},unknowns=['Reachability of a first-current-term commitment caused by switchToConfig while an earlier read is pending needs history analysis.'])
