F=[dict(id='F_authority',meaning='The node records a local term and role; becoming leader results from winning the configured vote quorum, while follower/pre-candidate states do not assert leader authority.',identity={'node':'raft.id','term':'raft.Term'},validity_context='Local role/term and current applied configuration; role can change without term change.',representation=['raft.Term','raft.Vote','raft.state','raft.lead','tracker.Votes'],invalidators=['B_context_reset'],reinterpreters=['B_configuration'],durability='Term and vote enter HardState and must be persisted; role, leader and tally are volatile.',recovery='newRaft reloads HardState/configuration and becomes follower.',source_ids=['S_campaign','S_dispatch','S_restore_init']),dict(id='F_committed',meaning='This local log records a committed prefix ending at committed. It does not assert completion of state-machine application or local persistence of every exposed entry.',identity={'node':'raft.id','prefix_end':'raftLog.committed'},validity_context='Log identity is index/term; commitment survives later terms. Leader advancement qualifies current-term quorum support; follower advancement uses leader matching-prefix evidence; recovery uses supplied persisted state.',representation=['raftLog.committed','HardState.Commit'],invalidators=[],reinterpreters=[],durability='HardState commit and log/snapshot persistence are caller duties; committed is an in-memory observation until processed.',recovery='Loaded HardState and snapshot reconstruct the prefix.',source_ids=['S_log_append','S_log_commit','S_log_context','S_config','S_restore_init','S_restore']),dict(id='F_config',meaning='The node currently uses the installed incoming/outgoing voter sets and learner roles; AutoLeave marks that Raft owns initiation of leaving this joint configuration. This fact does not assert that an exit proposal has been admitted.',identity={'node':'raft.id','configuration':'applied incoming/outgoing voters and learners'},validity_context='Until another applied configuration or restored snapshot replaces it; joint voters remain authoritative during any pending automatic exit.',representation=['tracker.Config.Voters','tracker.Config.Learners','tracker.Config.LearnersNext','tracker.Config.AutoLeave'],invalidators=['B_configuration','B_recovery'],reinterpreters=[],durability='Configuration is reflected in applied ConfState and snapshots, with committed entries for replay; volatile tracker state is not itself persistence.',recovery='confchange.Restore reconstructs voters and passes snapshot AutoLeave to EnterJoint.',source_ids=['S_conf_contract','S_confchange','S_tracker','S_restore_config'],unknowns=['Configuration export via Clone may omit AutoLeave without changing the active tracker.'])]
roles=json.load(open('../research.json'))['activity_roles']
summaries={'A1':'Leader proposals are replicated and durable support is aggregated using configured voters; current-term qualification controls commitment, which followers learn through matched append or bounded heartbeat commit.','A2':'Term/role changes, quorum elections and transfers acquire or revoke authority; reset discards volatile support but retains established log decisions.','A3':'In-repository restart and snapshot mechanisms reconstruct eligible history and configuration; persistence is caller-provided.','A4':'In-repository Changer validates simple/joint transitions; application determines activation and automatic exit ownership.','A5':'Committed Ready entries are consumed by the caller; in-repository accounting and completion responses determine subsequent application availability and joint-exit attempts.','A6':'In-repository Ready/worker-message scheduling enforces persistence dependencies, with caller-provided storage and recovery input.','A7':'Proposal admission does not guarantee commitment; read-index correlation and application waits are caller responsibilities, supported by library quorum-read processing.'}
audit=dict(version=1,target_profile=dict(system_boundary='Captured go.etcd.io/raft/v3 library: raft state machine, Node/RawNode APIs, tracker/quorum, configuration changes, Ready and Storage interfaces. Network, durable storage implementation and user state machine are caller-owned; their library-facing duties remain applicable.',protocol_contexts=['One raft group with nonzero unique node IDs','Terms, log index/term identity, applied simple or joint voter configuration'],external_interfaces=['Node/RawNode Step, Tick, Ready, Advance, Propose, ApplyConfChange, TransferLeadership','Storage, HardState, snapshots and asynchronous local append/apply messages'],ownership=['Node serializes requests in its run loop; RawNode callers serialize access.','Caller supplies transport, persistence and ordered application.'],variants=['Conventional and asynchronous storage writes','PreVote, CheckQuorum, safe versus lease reads','Simple and joint configuration transitions'],source_ids=['S_usage','S_async_contract','S_node_contract','S_node_loop','S_raw_ready']),activities=[dict(class_id=a,applicability='applicable',purpose=roles[a]['relation'],realization_summary=summaries[a],source_ids=sorted(set(s for b in B if b['primary_activity']==a for s in b['source_ids']))) for a in roles],behaviors=B,facts=F,surfaces=[dict(entry_point='tracker.Config.Clone -> getStatus',disposition='deferred',reason='Clone copies voter/learner maps but omits AutoLeave; getStatus uses the clone. Active Changer EnterJoint explicitly sets AutoLeave and LeaveJoint clears it, so export loss must not be conflated with active transition loss.',source_ids=['S_tracker','S_status','S_confchange']),dict(entry_point='raft.switchToConfig -> maybeCommit',disposition='deferred',reason='Configuration-driven commit does not release pending pre-first-commit reads; legal reachability must account for the campaign guard against unapplied committed configuration entries.',source_ids=['S_config','S_campaign','S_ack']),dict(entry_point='raft.appliedTo -> automatic joint exit',disposition='mapped',behavior_ids=['B_application','B_transfer','B_configuration'],reason='Specific continuation question selected; map association is not resolution.',source_ids=['S_auto_leave','S_timers','S_transfer'],high_consequence=True)],core_overview=dict(status='usable',rationale='Representative formation and authority paths plus their supporting history, membership, recovery and completion boundaries have been traced. Local continuation and export anomalies remain open, not global readiness gaps.',formation=dict(explanation='A leader assigns index and term to accepted proposals and queues a self acknowledgement behind persistence. Followers verify the predecessor term, replace only an uncommitted conflicting suffix, and return append responses after storage processing. Leader Match values are aggregated over the applied configuration: joint configurations require both majorities, and maybeCommit additionally requires current-term log identity. Changed commitment is broadcast; follower heartbeats are capped at known Match. Ready exposes committed entries for ordered caller application, and completion advances applied separately from committed.',behavior_ids=['B_replication','B_storage_ready','B_application'],fact_ids=['F_committed','F_config','F_authority'],source_ids=['S_commit_reset','S_ack','S_receive','S_log_append','S_joint','S_raw_ready','S_raw_completion']),context=dict(explanation='Tick or explicit campaign begins an election only for an eligible voter without pending snapshots or committed unapplied configuration changes. Vote choice is conditioned on local vote/leader state and candidate log freshness, with persistence-dependent replies and joint quorum counting. Higher terms normally install follower state; pre-vote and lease checks qualify this rule. Reset clears volatile aggregation and read-ack context, transfer target and pending configuration index, while committed history remains. Leader transfer pauses proposals, catches up a voter and sends TimeoutNow; it aborts on timeout or membership removal. Configuration changes activate on application, and snapshots/restart reconstruct configuration and history.',behavior_ids=['B_election','B_context_reset','B_transfer','B_configuration','B_recovery'],fact_ids=['F_authority','F_config','F_committed'],source_ids=['S_campaign','S_dispatch','S_timers','S_roles','S_config','S_restore']),connection=dict(explanation='Applied voter membership supplies both election and replication quorum meaning. A new leader resets peer Match and conservatively postpones new configuration changes until its inherited log tail is applied; its empty current-term entry enables safe commitment of older history. Old network replies are filtered by term and role, while old storage append completion cannot stabilize overwritten entries. Committed application and snapshot completion remain term-independent. Pending reads waiting for a first current-term commit are distinct from the reset read-ack queue. Applied joint configurations continue to require outgoing and incoming quorums until a leave entry is committed and applied; application completion attempts automatic exit but transfer admission can reject that proposal.',behavior_ids=['B_election','B_context_reset','B_replication','B_configuration','B_application','B_storage_ready','B_reads'],fact_ids=['F_config','F_authority','F_committed'],source_ids=['S_campaign','S_dispatch','S_config','S_auto_leave','S_proposal','S_read_release']),open_details=['Automatic exit continuation after a failed leadership transfer with no new client proposals.','AutoLeave representation in status copies.','Legal reachability of pending-read release differences at configuration-driven commitment.','Deeper snapshot, flow-control and client cancellation variants are not fully mapped.'],core_gaps=[]))
json.dump(audit,open('initial-map.json','w'),indent=2)
q=dict(question='When application completion attempts to leave an implicit joint configuration during a leadership transfer, does the same leader retain an implementation-owned continuation after the transfer times out, or can the active AutoLeave configuration remain without an exit proposal unless unrelated client work arrives?',importance='A stranded joint configuration can retain outgoing quorum requirements and prevent later membership changes; this is a potential configuration-progress consequence, not a measured safety violation.',source_ids=['S_auto_leave','S_timers','S_transfer','S_conf_contract','S_node_contract'],participants=['Current leader','Transfer target','Incoming and outgoing voters','Application/Ready owner'],objects=['Active joint configuration','Empty leave-joint proposal','leadTransferee','Applied/pendingConfIndex'],contexts=['Implicit joint transition already committed and applied','Transfer overlaps the completion callback that attempts automatic exit','Transfer times out while leader remains active and voter quorums communicate'],event_paths=['ApplyConfChange -> Advance/MsgStorageApplyResp -> appliedTo -> MsgProp rejected due to leadTransferee','Tick -> tickHeartbeat -> abortLeaderTransfer; future heartbeat/Ready processing'],activity_classes=['A4','A2'],behavior_ids=['B_configuration','B_application','B_transfer'],fact_ids=['F_config'],supporting_behavior_ids={'B_storage_ready':'Determines which caller completion events invoke appliedTo and whether another such event is guaranteed.','B_replication':'Establishes committed configuration entry and can create later application callbacks.','B_election':'A successful transfer/new leader creates a new entry, an alternative continuation outside the failed-transfer case.'},obligation_relation_kind='consumption',counterevidence=['appliedTo retries on later applied entries.','Successful transfer gives a new leader an empty entry and a later completion opportunity.','Client proposals may be retried by callers, but ownership of the internal implicit-exit retry must be distinguished.'],unknowns=['Does ordinary heartbeat-only Ready/Advance processing after timeout invoke appliedTo when it has no committed entries?','Construct one legal prefix with the joint entry fully committed and applied, transfer still active at its completion callback, and no guaranteed later application work.','Determine the precise automatic-exit duty and scheduling assumptions without inventing a numeric deadline.'],trigger_rationale='The source explicitly allows transfer to reject the internal exit attempt, while its timeout only clears leadTransferee. A small deterministic RawNode schedule can distinguish ordinary completion retry from dependence on a new application entry. This progress premise is more consequential than the separate status-copy omission and more directly sourced than the uncertain config-commit read-release history.',disposition='concrete_suspicion',preferred_check='controlled_schedule')
